{
  "$schema": "https://opencode.ai/config.json",
  "model": "anthropic/claude-sonnet-4-5",
  "small_model": "google/gemini-2.5-flash",
  "lsp": {
    "typescript": {
      "command": ["bunx", "typescript-language-server", "--stdio"],
      "extensions": [".ts", ".tsx", ".mts"]
    }
  },
  "agent": {
    "plan": {
      "description": "Kien truc su chi doc: phan tich monorepo va lap ke hoach truoc khi sua code",
      "mode": "primary",
      "permission": {
        "edit": "deny",
        "bash": "deny",
        "webfetch": "allow"
      }
    },
    "build": {
      "description": "Ky su thuc thi: viet code TypeScript co Live LSP va chay test cuc bo",
      "mode": "primary",
      "permission": {
        "edit": "allow",
        "bash": {
          "*": "ask",
          "pnpm test*": "allow",
          "pnpm lint*": "allow",
          "git status*": "allow",
          "git diff*": "allow",
          "rm -rf*": "deny"
        }
      }
    },
    "rls-reviewer": {
      "description": "Subagent ra soat SQL migration va chinh sach PostgreSQL FORCE RLS",
      "mode": "subagent",
      "permission": {
        "edit": "deny",
        "bash": "deny"
      }
    }
  },
  "mcp": {
    "context7": {
      "type": "local",
      "command": ["npx", "-y", "@upstash/context7-mcp"],
      "enabled": true
    },
    "github-readonly": {
      "type": "local",
      "command": ["docker", "run", "-i", "--rm", "-e", "GITHUB_PERSONAL_ACCESS_TOKEN", "ghcr.io/github/github-mcp-server", "--read-only", "--toolsets=repos,issues,pull_requests"],
      "enabled": true
    }
  }
}
